#!/usr/bin/env python3
"""Router / cascade for the tools layer (stdlib only). Only used when the round folder holds round_config.json.

A model's tool call becomes one request. The router, never the model, fixes the path from the request's scope:
  L0 store            parked answer for the key (free)
  L1 file             allow-listed docs (round_config "docs": glossary, harness context file) (free)
  L2 search           Tavily via tavily_search.run(), called by this script, never by a paid model (credits); if
                      search_filter_model is a DeepSeek model, that cheap model filters the results before they are
                      parked (its cost is a cost record in the store and counts toward fetch_budget_usd/round_budget_usd)
  L3 claude_code      review_claude_code.info_request(), read-only (paid, CLI-reported cost)
  L4 human            appended to <round-dir>/to_danny/questions.jsonl, only if cascade_allow_human is true

  scope doc:<name>  L0 -> L1
  scope rig         L0 -> L3 -> L4      never L2 (stop rule 4)
  scope repo        L0 -> L3 -> L4
  scope external    L0 -> L2 -> L4
  ask_claude_code   L0 -> L3 -> L4 (scope repo)

Stop rules: (1) first complete answer; (2) cascade_max_hops levels visited (store included) -> unresolved;
(3) budget -> budget_stop: round_budget_usd is the round TOTAL (model replies + fetches, round_budget.py);
fetch_budget_usd caps fetch spend alone; also search_credits_per_round and claude_code_max_budget_usd;
(4) rig scope never searches; unanswered rig -> missing_in_context_file; (5) decision lists (DESIGN_STATE.md,
harness/locked_values.yml, harness/retired.txt) are never served by this router: decisions reach the four API models

(6) a level never runs twice for one request. Paid levels (L2, L3) go through the waiters queue: one fetch per key,
concurrent askers wait for it. Every request appends one line to <round-dir>/flow_log.jsonl.
All parameters come from round_config params and are required up front (fail closed).

Store contents: fetched answers only. Claude Code's routed answers are split: `facts` (looked-up information with
sources) are parked; `decisions` are delivered to the asker in-round, logged in flow_log (kind=decision,
parked=false) and kept in the round's decisions cache (<round-dir>/decisions_cache.jsonl), never in the store or the
reference folder. A later asker of the same question gets the parked facts plus the cached decisions (no re-ask).
At close the cache is sealed (moved) into <round-dir>/archive/, so the next round starts with an empty cache.
Never reachable through this router: the Claude Code reference folder (claude_code_reference_path), the round
archive, the decisions cache and the store files. No read_doc path may point into them, and L1 refuses them.
"""
from __future__ import annotations

import fcntl
import json
import os
import re
import sys
import time
from pathlib import Path

sys.path.insert(0, os.path.dirname(__file__))
import harness_common as hc  # noqa: E402
import harness_store as hs  # noqa: E402
import round_config as rc  # noqa: E402

ROOT = hc.ROOT
FLOW_LOG = "flow_log.jsonl"
SCOPES = ("repo", "rig", "external")
ROUTES = {
    "doc": ("L0", "L1"),
    "rig": ("L0", "L3", "L4"),
    "repo": ("L0", "L3", "L4"),
    "external": ("L0", "L2", "L4"),
    "ask_claude_code": ("L0", "L3", "L4"),
}
ANSWERED_BY = {"L0": "store", "L1": "file", "L2": "tavily", "L3": "claude_code", "L4": "human_queue"}
TERMINAL = {"answered", "missing_in_context_file", "budget_stop", "waiter_timeout", "pending_human", "unresolved"}
PARKABLE = {"answered", "missing_in_context_file"}
ROUTER_PARAMS = ("store_scope", "store_max_age_s", "waiter_timeout_s", "waiter_poll_s", "inflight_lease_s",
                 "cascade_max_hops", "cascade_allow_human", "round_budget_usd", "fetch_budget_usd",
                 "search_credits_per_round", "search_filter_model", "claude_code_max_budget_usd",
                 "claude_code_timeout_s", "claude_code_reference_path")
TEMPLATE_MARK = "[FILL IN]"
# Search filter (D13b). Seen only by the filter model, never by the four answering models.
FILTER_PROMPT = ("Question:\n{question}\n\nSearch results (JSON list, index i = position):\n{results}\n\n"
                 "Return the indexes of the results that help answer the question. Reply with one fenced json block "
                 'only: {{"keep": [0, 2]}}')
# Decision lists: never served to the API models by read_doc / request_info (Claude Code reads them himself).
DECISION_FILES = ("DESIGN_STATE.md", "harness/locked_values.yml", "harness/retired.txt")


def _append_jsonl(path: Path, rec: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "a") as fh:
        fcntl.flock(fh, fcntl.LOCK_EX)
        try:
            fh.write(json.dumps(rec, sort_keys=True) + "\n")
            fh.flush()
        finally:
            fcntl.flock(fh, fcntl.LOCK_UN)


def _inside(path, folder) -> bool:
    if folder is None or not path:
        return False
    p = Path(str(path))
    p = (p if p.is_absolute() else ROOT / p).resolve()
    folder = Path(folder).resolve()
    return p == folder or folder in p.parents


def log_event(round_dir, rec: dict) -> None:
    _append_jsonl(Path(round_dir) / FLOW_LOG, {"ts": hs.now_utc(), **rec})


def log_native_reads(round_dir, model: str, run_id, stage: str, reads, reference=None) -> None:
    """Copy a tool-using model's own file reads (e.g. Claude Code's transcript) into the flow log."""
    for i, r in enumerate(reads or [], 1):
        inp = r.get("input") or {}
        log_event(round_dir, {
            "run_id": run_id, "stage": stage, "asked_by": model, "tool": "native_read",
            "native_tool": r.get("tool"), "input": inp, "seq_in_reply": i, "cache": None,
            "used_reference": any(_inside(inp.get(k), reference) for k in ("file_path", "path")),
            "answered_by": model, "final_status": "native", "cost_usd": 0})


def _filter_price(model):
    """(input, cached, output) USD per 1M tokens at peak for a DeepSeek model, or None."""
    import review_deepseek as rd
    return next((v for k, v in rd.PRICES.items() if str(model).startswith(k)), None)


def filter_worst_case_usd(model, prompt: str, max_tokens: int) -> float:
    """Upper bound for one filter call: every prompt byte a token at the peak input price, plus max_tokens output."""
    p = _filter_price(model)
    return (len(prompt.encode()) * p[0] + int(max_tokens) * p[2]) / 1e6


def _default_filter(model, prompt, max_tokens):
    """One DeepSeek call through oai_compat (DEEPSEEK_BASE_URL honoured). Returns text, cost_usd, usage, model, finish."""
    import oai_compat as oc
    import review_deepseek as rd
    key = os.environ.get(rd.DEEPSEEK.secret, "").strip()
    if not key:
        raise RuntimeError(f"{rd.DEEPSEEK.secret} is not set; search filter not run")
    text, u, m, stop, _ = oc.chat(rd.DEEPSEEK, {"deepseek_idle_timeout_s": 120, "deepseek_deadline_s": 300}, key,
                                  [{"role": "user", "content": prompt}], max_tokens=max_tokens, model=model)
    return {"text": text, "cost_usd": u.get("cost_usd"), "usage": {k: u.get(k) for k in
            ("input_tokens", "cached_input_tokens", "output_tokens", "reasoning_tokens")}, "model": m, "finish": stop}


def _parse_keep(text, n):
    m = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", text or "", re.S)
    try:
        v = json.loads(m.group(1) if m else (text or "").strip())
    except (json.JSONDecodeError, AttributeError):
        return None
    keep = v.get("keep") if isinstance(v, dict) else None
    if not isinstance(keep, list):
        return None
    out = []
    for i in keep:
        if isinstance(i, int) and not isinstance(i, bool) and 0 <= i < n and i not in out:
            out.append(i)
    return out


def _default_search(query, max_results, search_depth):
    import tavily_search as ts
    return ts.run(query, max_results, search_depth)


class Router:
    def __init__(self, round_dir, asked_by: str, run_id=None, stage: str = "primary",
                 search_fn=None, claude_code_fn=None, cfg: rc.RoundConfig | None = None, filter_fn=None):
        self.cfg = cfg or rc.require_config(round_dir)
        self.round_dir = self.cfg.round_dir
        self.p = self.cfg.require(*ROUTER_PARAMS)               # fail closed before anything runs
        fm = self.p["search_filter_model"]
        if fm != "none":
            if not str(fm).startswith("deepseek"):
                raise NotImplementedError(f"search_filter_model {fm!r}: only 'none' or a DeepSeek model is built")
            self.filter_max_tokens = int(self.cfg.param("search_filter_max_tokens"))
            if _filter_price(fm) is None:
                raise ValueError(f"search_filter_model {fm!r} has no price on file; refusing (cost must count)")
        self.filter_fn = filter_fn or _default_filter
        self.ref = self.cfg.reference_dir()
        self.decisions_cache = self.cfg.round_dir / hs.DECISIONS_CACHE
        self.denied = {"the Claude Code reference folder": self.ref,
                       "the round archive": self.cfg.round_dir / hs.ARCHIVE_DIR,
                       "the decisions cache": self.decisions_cache,
                       "the store": self.cfg.round_dir / "store",
                       **{f"a decision list ({f})": ROOT / f for f in DECISION_FILES}}
        self.docs = {}
        for name, path in self.cfg.docs.items():
            if not path:
                raise rc.MissingParameter(f"docs.{name}", "read_doc path")
            for what, folder in self.denied.items():
                if _inside(path, folder):
                    raise ValueError(f"docs.{name} points into {what}; refusing")
            self.docs[name] = path
        self.store = hs.Store(self.cfg.store_dir())
        self.asked_by, self.run_id, self.stage = asked_by, run_id, stage
        self.search_fn = search_fn or _default_search
        self.claude_code_fn = claude_code_fn
        self.seq = 0
        tav = hc.load_dial().get("tavily") or {}
        self.tavily = {"max_results": tav.get("max_results"), "search_depth": tav.get("search_depth")}
        self.epoch = hs.epoch_of([self._abs(p) for p in self.docs.values()]
                                 + [ROOT / "harness" / "locked_values.yml", ROOT / "harness" / "retired.txt"])

    # ---------- public ----------
    def handle(self, tool: str, args: dict, turn: int | None = None) -> dict:
        """Run one tool call; return the result given back to the model. Always logs one flow_log line."""
        self.seq += 1
        t0 = time.monotonic()
        args = args if isinstance(args, dict) else {}
        try:
            question, scope, route = self._parse(tool, args)
        except ValueError as e:
            result = {"status": "bad_request", "error": str(e)}
            self._log(tool, args, None, None, [], result, t0, turn)
            return self._model_view(result)
        key = hs.store_key(question, scope, self.epoch)
        hops, result = self._cascade(question, scope, route, key)
        self._log(tool, args, scope, key, hops, result, t0, turn, question=question)
        return self._model_view(result)

    def _model_view(self, result: dict) -> dict:


        store_key and every other internal field
        stay in flow_log.jsonl (self.last keeps the full result for this process only)."""
        self.last = dict(result)

            return {"status": "bad_request", "error": result.get("error")}
        out = {"status": result["status"], "answer": result.get("answer"),
               "complete": bool(result.get("complete")), "cites": list(result.get("cites") or [])}
        if result.get("decisions"):
            out["decisions"] = result["decisions"]
        return out

    # ---------- parsing ----------
    def _parse(self, tool, args):
        if tool == "read_doc":
            name = args.get("name")
            if name not in self.docs:
                raise ValueError(f"unknown document {name!r}")
            return f"read_doc {name}", f"doc:{name}", ROUTES["doc"]
        q = str(args.get("question") or "").strip()
        if not q:
            raise ValueError("question is empty")
        if tool == "request_info":
            scope = args.get("scope")
            if scope not in SCOPES:
                raise ValueError(f"scope must be one of {', '.join(SCOPES)}")
            return q, scope, ROUTES[scope]
        if tool == "ask_claude_code":
            return q, "repo", ROUTES["ask_claude_code"]
        raise ValueError(f"unknown tool {tool!r}")

    # ---------- cascade ----------
    def _cascade(self, question, scope, route, key):
        hops, visited, out = [], [], None
        for level in route:
            if level in visited:                                          # stop rule 6
                continue
            if len(visited) >= int(self.p["cascade_max_hops"]):           # stop rule 2
                out = {"status": "unresolved", "reason": "cascade_max_hops"}
                break
            visited.append(level)
            t = time.monotonic()
            o = getattr(self, f"_{level}")(question, scope, key)
            hops.append({"level": level, "outcome": o["status"], "cost_usd": o.get("cost_usd", 0),
                         "credits": o.get("credits", 0), "ms": int((time.monotonic() - t) * 1000),
                         **({"note": o["note"]} if o.get("note") else {})})
            if o["status"] in TERMINAL:
                out = o
                break
        if out is None:
            out = {"status": "missing_in_context_file" if scope == "rig" else "unresolved"}
        if out.get("level") == "L0" and "L3" in route:
            cached = self._cached_decisions(key)           # decisions are not in the store: serve them from the cache
            if cached:
                out = {**out, "decisions": cached, "decisions_from_cache": True}
        if (out["status"] in PARKABLE and out.get("level") not in ("L0", None) and out.get("park", True)
                and not out.get("parked")):
            self._park(key, question, scope, out)
        result = {"status": out["status"], "answer": out.get("answer"), "source_level": out.get("level"),
                  "cache_hit": out.get("cache") in ("hit", "waited"), "store_key": key,
                  "complete": out["status"] == "answered", "cites": out.get("cites", [])}
        if out.get("decisions"):
            result["decisions"] = [{"decision": d["decision"], "cites": d["cites"]} for d in out["decisions"]]
            if not out.get("decisions_logged"):
                self._log_decisions(key, out["decisions"], from_cache=bool(out.get("decisions_from_cache")))
        result["_used_reference"] = bool(out.get("used_reference"))
        result["_answered_by"] = out.get("answered_by")
        result["_cache"] = out.get("cache") or "miss"
        result["_waited_on"] = out.get("waited_on")
        return hops, result

    def _park(self, key, question, scope, out) -> None:
        """Park the fetched answer (facts only; decisions are never passed in here)."""
        self.store.park(key, question=question, scope=scope, status=out["status"], answer=out.get("answer"),
                        cites=out.get("cites", []), answered_by=out.get("answered_by"), level=out.get("level"),
                        asked_by=self.asked_by, run_id=self.run_id,
                        used_reference=bool(out.get("used_reference")))
        out["parked"] = True

    def _log_decisions(self, key, decisions, from_cache: bool = False) -> None:
        for d in decisions:
            log_event(self.round_dir, {"kind": "decision", "parked": False, "from_cache": from_cache,
                                       "run_id": self.run_id, "stage": self.stage, "asked_by": self.asked_by,
                                       "store_key": key, "decision": d["decision"], "cites": d["cites"],
                                       "answered_by": "claude_code", "used_reference": d.get("used_reference")})
            if not from_cache:
                _append_jsonl(self.decisions_cache, {"ts": hs.now_utc(), "store_key": key, "decision": d["decision"],
                                                     "cites": d["cites"], "run_id": self.run_id,
                                                     "asked_by": self.asked_by,
                                                     "used_reference": d.get("used_reference")})

    # L0 ----------
    def _L0(self, question, scope, key):
        rec = self.store.lookup(key, self.p["store_max_age_s"])
        if rec is None:
            return {"status": "miss", "cache": "miss"}
        return {"status": rec["status"], "answer": rec.get("answer"), "cites": rec.get("cites", []), "level": "L0",
                "answered_by": rec.get("answered_by"), "cache": "hit"}

    # L1 ----------
    def _abs(self, rel) -> Path:
        p = Path(rel)
        return p if p.is_absolute() else ROOT / p

    def _L1(self, question, scope, key):
        if scope.startswith("doc:"):
            name = scope[4:]
            f = self._abs(self.docs[name])
            if any(_inside(f, folder) for folder in self.denied.values()):  # defence in depth
                return {"status": "unresolved", "note": "path not allowed"}
            if not f.is_file():
                return {"status": "unresolved", "note": f"{self.docs[name]} not found"}
            text = f.read_text(errors="replace")
            n = len(text.splitlines())
            if name == "harness_context" and TEMPLATE_MARK in text:
                return {"status": "missing_in_context_file", "level": "L1", "answered_by": "file",
                        "answer": None, "note": "harness context file still has [FILL IN] blanks"}
            return {"status": "answered", "answer": text, "cites": [f"{self.docs[name]}:1-{max(n, 1)}"],
                    "level": "L1", "answered_by": "file"}
        return {"status": "miss"}                                         # rig/repo never read files here

    # paid levels share the waiters queue ----------
    def _once(self, key, fetch):
        owner = f"{self.asked_by}:{os.getpid()}"
        for attempt in range(2):
            if self.store.acquire(key, owner, self.p["inflight_lease_s"]):
                try:
                    rec = self.store.lookup(key, self.p["store_max_age_s"])
                    if rec is not None:
                        return {"status": rec["status"], "answer": rec.get("answer"), "cites": rec.get("cites", []),
                                "level": "L0", "answered_by": rec.get("answered_by"), "cache": "hit"}
                    return fetch()
                finally:
                    self.store.release(key)
            state, rec = self.store.wait_for(key, self.p["waiter_timeout_s"], self.p["waiter_poll_s"],
                                             self.p["store_max_age_s"])
            if state == "answer":
                return {"status": rec["status"], "answer": rec.get("answer"), "cites": rec.get("cites", []),
                        "level": "L0", "answered_by": rec.get("answered_by"), "cache": "waited",
                        "waited_on": "in-flight fetch"}
            if state == "timeout":
                return {"status": "waiter_timeout", "cache": "waited"}
            # released with no parked answer: the other fetch came back empty; do not pay for it twice
            return {"status": "miss", "cache": "waited", "note": "concurrent fetch returned no answer"}
        return {"status": "miss"}

    # budget ----------
    def _round_left(self) -> float:
        """What is left of the round total (model replies + fetches)."""
        return float(self.p["round_budget_usd"]) - self.store.spent()["usd"]

    def _fetch_left(self) -> float:
        """What is left of the fetch cap (fetch spend only)."""
        return float(self.p["fetch_budget_usd"]) - self.store.spent()["fetch_usd"]

    def _budget_stop(self):
        if self._round_left() <= 0:
            return {"status": "budget_stop", "note": "round_budget_usd (round total) reached"}
        if self._fetch_left() <= 0:
            return {"status": "budget_stop", "note": "fetch_budget_usd reached"}
        return None

    # L2 ----------
    def _L2(self, question, scope, key):
        if scope == "rig":                                                # stop rule 4 (defensive)
            return {"status": "miss", "note": "rig scope never searches"}
        stop = self._budget_stop()
        if stop:
            return stop
        depth = self.tavily["search_depth"]
        if self.tavily["max_results"] is None or depth is None:
            raise rc.MissingParameter("tavily.max_results/search_depth", "harness/dial.yml")
        need = 2 if depth == "advanced" else 1                            # Tavily's own credit price per search
        if self.store.spent()["credits"] + need > int(self.p["search_credits_per_round"]):
            return {"status": "budget_stop", "note": "search_credits_per_round"}

        fm = self.p["search_filter_model"]
        if fm != "none":                                                  # the filter's output cap must fit
            out_only = int(self.filter_max_tokens) * _filter_price(fm)[2] / 1e6
            if out_only > min(self._fetch_left(), self._round_left()):
                return {"status": "budget_stop", "note": "search filter cannot fit fetch_budget_usd/round_budget_usd"}

        def fetch():
            rec = self.search_fn(question, int(self.tavily["max_results"]), depth)
            credits = int(rec.get("credits") or 0) if rec.get("status") == "ok" else 0
            self.store.append("cost", level="L2", store_key=key, credits=credits, cost_usd=0,
                              source_type="info_fetch", asked_by=self.asked_by, run_id=self.run_id,
                              search_status=rec.get("status"), reviewer="Tavily", model="tavily-search")
            res = rec.get("results") or []
            if rec.get("status") != "ok" or not res:
                return {"status": "miss", "credits": credits, "note": f"tavily {rec.get('status')}"}
            items = [{"title": r.get("title"), "url": r.get("url"),               # tavily_search.run() calls it
                      "content": r.get("content") or r.get("snippet")} for r in res]     # "snippet"
            cost, note = 0.0, None
            if fm != "none":
                items, cost, note = self._filter(question, key, items)
                if items is None:
                    return {"status": "budget_stop", "credits": credits, "cost_usd": cost, "note": note}
                if not items:
                    return {"status": "miss", "credits": credits, "cost_usd": cost,
                            "note": note or "search filter kept no results"}
            out = {"status": "answered", "level": "L2", "answered_by": "tavily", "credits": credits,
                   "cost_usd": cost, "answer": items, "cites": [r["url"] for r in items if r.get("url")],
                   **({"note": note} if note else {})}
            self._park(key, question, scope, out)          # parked before the in-flight marker is released
            return out
        return self._once(key, fetch)

    def _filter(self, question, key, items):
        """Run the search filter. Returns (kept_items | None for budget_stop, cost_usd, note)."""
        fm = self.p["search_filter_model"]
        prompt = FILTER_PROMPT.format(question=question, results=json.dumps(
            [{"i": i, **it} for i, it in enumerate(items)], ensure_ascii=False))
        worst = filter_worst_case_usd(fm, prompt, self.filter_max_tokens)
        if worst > min(self._fetch_left(), self._round_left()):
            return None, 0.0, (f"search filter worst case ${worst:.4f} exceeds what is left of "
                               f"{'fetch_budget_usd' if worst > self._fetch_left() else 'round_budget_usd'}")
        try:
            r = self.filter_fn(fm, prompt, self.filter_max_tokens) or {}
        except Exception as e:  # noqa: BLE001
            self.store.append("cost", level="L2", store_key=key, credits=0, cost_usd=0, source_type="info_fetch",
                              asked_by=self.asked_by, run_id=self.run_id, reviewer="DeepSeek", model=fm,
                              purpose="search_filter", error=str(e)[:300])
            return items, 0.0, f"search filter failed ({type(e).__name__}); results passed unfiltered"
        cost = float(r.get("cost_usd") or 0)
        self.store.append("cost", level="L2", store_key=key, credits=0, cost_usd=cost, source_type="info_fetch",
                          asked_by=self.asked_by, run_id=self.run_id, reviewer="DeepSeek", model=r.get("model") or fm,
                          purpose="search_filter", tokens=r.get("usage"), finish=r.get("finish"))
        keep = _parse_keep(r.get("text"), len(items))
        if keep is None:
            return items, cost, "search filter reply unreadable; results passed unfiltered"
        return [items[i] for i in keep], cost, f"search filter kept {len(keep)} of {len(items)}"

    # L3 ----------
    def _cached_decisions(self, key) -> list[dict]:
        f = self.decisions_cache
        if not f.is_file():
            return []
        seen, out = set(), []
        for line in f.read_text().splitlines():
            r = json.loads(line) if line.strip() else {}
            if r.get("store_key") == key and r.get("decision") not in seen:
                seen.add(r["decision"])
                out.append({"decision": r["decision"], "cites": r.get("cites", []),
                            "used_reference": r.get("used_reference")})
        return out

    def _cc_fn(self, key):
        if self.claude_code_fn is not None:
            return self.claude_code_fn
        import review_claude_code as rcc

        def fn(q, s, b):
            return rcc.info_request(q, s, self.cfg, b, self.store.dir / "claude_code" / key,
                                    log_ctx={"asked_by": self.asked_by, "run_id": self.run_id,
                                             "stage": self.stage, "store_key": key})
        return fn

    def _L3_fetch(self, question, scope, key, reask=False):
        stop = self._budget_stop()
        if stop:
            return stop
        budget = min(self._round_left(), self._fetch_left(), float(self.p["claude_code_max_budget_usd"]))
        r = self._cc_fn(key)(question, scope, budget) or {}
        cost = float(r.get("cost_usd") or 0)
        self.store.append("cost", level="L3", store_key=key, cost_usd=cost, credits=0, source_type="info_fetch",
                          reviewer="Claude Code", model=r.get("model"),
                          asked_by=self.asked_by, run_id=self.run_id, answered_by="claude_code",
                          finish=r.get("finish"), reask_for_decisions=reask)
        if r.get("reads"):
            log_native_reads(self.round_dir, "claude_code", self.run_id, f"switch:{key}", r["reads"], self.ref)
        facts = [{"fact": x["fact"], "cites": x["cites"]} for x in r.get("facts") or [] if x.get("cites")]
        decisions = [x for x in r.get("decisions") or [] if x.get("cites")]
        used_ref = bool(r.get("used_reference"))
        if r.get("complete") is True and (facts or decisions):
            out = {"status": "answered", "level": "L3", "answered_by": "claude_code", "cost_usd": cost,
                   "answer": facts or None, "cites": [c for x in facts for c in x["cites"]],
                   "decisions": decisions, "park": bool(facts), "used_reference": used_ref}
            if not reask:                       # before the in-flight marker is released, so waiters see both
                if decisions:
                    self._log_decisions(key, decisions)
                    out["decisions_logged"] = True
                if facts:
                    self._park(key, question, scope, out)
            return out
        return {"status": "miss", "cost_usd": cost, "decisions": decisions, "used_reference": used_ref,
                "note": r.get("error") or r.get("note") or "incomplete"}

    def _L3(self, question, scope, key):
        stop = self._budget_stop()
        if stop:
            return stop
        return self._once(key, lambda: self._L3_fetch(question, scope, key))

    # L4 ----------
    def _L4(self, question, scope, key):
        if self.p["cascade_allow_human"] is not True:
            return {"status": "missing_in_context_file" if scope == "rig" else "unresolved",
                    "note": "cascade_allow_human is false"}
        _append_jsonl(self.round_dir / "to_danny" / "questions.jsonl", {
            "ts": hs.now_utc(), "run_id": self.run_id, "stage": self.stage, "asked_by": self.asked_by,
            "question": question, "scope": scope, "store_key": key})
        return {"status": "pending_human", "level": "L4", "answered_by": "human_queue"}

    # ---------- flow log ----------
    def _log(self, tool, args, scope, key, hops, result, t0, turn, question=None):
        cost = sum(float(h.get("cost_usd") or 0) for h in hops)
        credits = sum(int(h.get("credits") or 0) for h in hops)
        _append_jsonl(self.round_dir / FLOW_LOG, {
            "ts": hs.now_utc(), "run_id": self.run_id, "stage": self.stage, "asked_by": self.asked_by,
            "tool": tool, "args": args, "question": question, "scope": scope, "store_key": key,
            "cache": result.get("_cache"), "waited_on": result.get("_waited_on"), "hops": hops,
            "answered_by": result.get("_answered_by"), "final_status": result["status"],
            "source_level": result.get("source_level"), "cache_hit": result.get("cache_hit"),
            **({"error": result["error"]} if result.get("error") else {}),
            "used_reference": bool(result.get("_used_reference")), "decisions_delivered": len(result.get("decisions") or []),
            "cost_usd": round(cost, 6), "credits": credits, "turn_index": turn, "seq_in_reply": self.seq,
            "ms": int((time.monotonic() - t0) * 1000)})
        for k in ("_cache", "_waited_on", "_answered_by", "_used_reference"):
            result.pop(k, None)

#!/usr/bin/env python3
"""Shared store + waiters queue for the tools layer (stdlib only, POSIX file locks).

Layout under <store_dir> (round_config.RoundConfig.store_dir()):
  info.jsonl          append-only log, one JSON object per line (sorted keys). Kinds: info_request, info_answer,
                      info_invalidate, cost. Never rewritten.
  index.json          derived: store_key -> latest valid info_answer. Rebuildable from info.jsonl at any time.
  inflight/<key>.lock waiters-queue marker held by the one process fetching <key>.

Keys: sha256(norm(question) | scope | epoch), first 16 hex. epoch = sha256 over the bytes of the round's epoch
files, so editing any of them changes every key and old answers are simply never hit again.
Timing values (lease, waiter timeout, poll interval, max age) are passed in by callers from round_config params.
"""
from __future__ import annotations

import fcntl
import hashlib
import json
import os
import re
import secrets
import time
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path

import ledger_lib

KINDS = ("info_request", "info_answer", "info_invalidate", "cost")

# decisions in there"). Records carrying any of these fields are refused.
DECISION_FIELDS = ("decision", "decisions", "verdict", "verdicts", "score", "scores", "choice", "design_choice",
                   "recommendation", "recommendations", "ruling", "approved", "adopted")
FACT_SOURCES = ("tavily", "claude_code")          # fetched (looked-up) answers; file reads are not promoted
REFERENCE_FILE = "facts.jsonl"
# In-round decisions cache (Claude Code's decision parts, delivered to askers; never in the store or the reference
# folder). Sealed into <round-dir>/archive/ at close (moved, never deleted); no model tool can reach the archive.
DECISIONS_CACHE = "decisions_cache.jsonl"
ARCHIVE_DIR = "archive"
TS_FMT = "%Y-%m-%dT%H:%M:%SZ"


def now_utc() -> str:
    return datetime.now(timezone.utc).strftime(TS_FMT)


def _ts(s: str) -> float:
    return datetime.strptime(s, TS_FMT).replace(tzinfo=timezone.utc).timestamp()


def norm_question(q: str) -> str:
    return re.sub(r"[\s?.!,;:]+$", "", ledger_lib._norm(q))


def epoch_of(paths) -> str:
    h = hashlib.sha256()
    for p in paths:
        p = Path(p)
        h.update(str(p.name).encode() + b"\x1f")
        h.update(p.read_bytes() if p.is_file() else b"<missing>")
        h.update(b"\x1e")
    return h.hexdigest()


def store_key(question: str, scope: str, epoch: str) -> str:
    return ledger_lib.dedup_hash(norm_question(question), scope, epoch)[:16]


def verify_append_only(old_text: str, new_text: str) -> bool:
    return new_text.startswith(old_text)


@contextmanager
def _locked(path: Path):
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "a+") as fh:
        fcntl.flock(fh, fcntl.LOCK_EX)
        try:
            yield fh
        finally:
            fcntl.flock(fh, fcntl.LOCK_UN)


class Store:
    def __init__(self, store_dir):
        self.dir = Path(store_dir)
        self.log = self.dir / "info.jsonl"
        self.index_path = self.dir / "index.json"
        self.inflight = self.dir / "inflight"
        self._lockfile = self.dir / ".store.lock"

    # ---------- append-only log ----------
    def append(self, kind: str, **fields) -> dict:
        if kind not in KINDS:
            raise ValueError(f"unknown record kind {kind!r}")
        bad = [k for k in fields if k.lower() in DECISION_FIELDS]
        if bad:
            raise ValueError(f"store holds fetched answers only; refusing decision-type field(s) {bad}")
        rec = {"kind": kind, "ts": now_utc(), "id": secrets.token_hex(8), **fields}
        line = json.dumps(rec, sort_keys=True) + "\n"
        with _locked(self._lockfile):
            with open(self.log, "a") as fh:
                fh.write(line)
                fh.flush()
                os.fsync(fh.fileno())
            if kind in ("info_answer", "info_invalidate"):
                idx = self._read_index()
                self._apply(idx, rec)
                self._write_index(idx)
        return rec

    def records(self) -> list[dict]:
        if not self.log.is_file():
            return []
        return [json.loads(x) for x in self.log.read_text().splitlines() if x.strip()]

    # ---------- index ----------
    @staticmethod
    def _apply(idx: dict, rec: dict) -> None:
        if rec["kind"] == "info_answer":
            idx[rec["store_key"]] = rec
        elif rec["kind"] == "info_invalidate":
            idx.pop(rec["store_key"], None)

    def _read_index(self) -> dict:
        if not self.index_path.is_file():
            return {}
        try:
            return json.loads(self.index_path.read_text())
        except json.JSONDecodeError:
            return self.rebuild_index(write=False)

    def _write_index(self, idx: dict) -> None:
        tmp = self.index_path.with_suffix(".json.tmp")
        tmp.write_text(json.dumps(idx, sort_keys=True, indent=1))
        os.replace(tmp, self.index_path)

    def rebuild_index(self, write: bool = True) -> dict:
        idx: dict = {}
        for r in self.records():
            if r["kind"] in ("info_answer", "info_invalidate"):
                self._apply(idx, r)
        if write:
            self.dir.mkdir(parents=True, exist_ok=True)
            self._write_index(idx)
        return idx

    # ---------- parked results ----------
    def lookup(self, key: str, max_age_s) -> dict | None:
        """Latest valid parked answer for key. max_age_s=False means answers never expire."""
        rec = self._read_index().get(key)
        if rec is None:
            return None
        if max_age_s is not False and (time.time() - _ts(rec["ts"])) > float(max_age_s):
            return None
        return rec

    def park(self, key: str, **fields) -> dict:
        return self.append("info_answer", store_key=key, **fields)

    def invalidate(self, key: str, reason: str) -> dict:
        return self.append("info_invalidate", store_key=key, reason=reason)

    # ---------- spend ----------
    def spent(self) -> dict:
        """usd = everything (round total: model replies + fetches); fetch_usd = info_fetch records only
        (fetch_budget_usd); reply_usd = model_reply records (round_budget.py)."""
        usd, credits, fetch, reply = 0.0, 0, 0.0, 0.0
        for r in self.records():
            if r["kind"] == "cost":
                c = float(r.get("cost_usd") or 0)
                usd += c
                credits += int(r.get("credits") or 0)
                if r.get("source_type") == "model_reply":
                    reply += c
                else:
                    fetch += c
        return {"usd": usd, "credits": credits, "fetch_usd": fetch, "reply_usd": reply}

    # ---------- waiters queue ----------
    def _lock_path(self, key: str) -> Path:
        return self.inflight / f"{key}.lock"

    def acquire(self, key: str, owner: str, lease_s) -> bool:
        """True if this caller now owns the fetch for key. Takes over a marker whose lease has expired."""
        self.inflight.mkdir(parents=True, exist_ok=True)
        p = self._lock_path(key)
        body = json.dumps({"owner": owner, "pid": os.getpid(), "started_utc": now_utc(),
                           "lease_until": time.time() + float(lease_s)})
        for _ in range(2):
            try:
                fd = os.open(p, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            except FileExistsError:
                try:
                    held = json.loads(p.read_text() or "{}")
                except (OSError, json.JSONDecodeError):
                    held = {}
                if held and time.time() <= float(held.get("lease_until", 0)):
                    return False
                stale = p.with_name(f"{p.name}.expired-{secrets.token_hex(4)}")
                try:
                    os.replace(p, stale)       # move the expired marker aside; only one taker wins the O_EXCL
                    self.append("info_request", store_key=key, event="lease_takeover", by=owner,
                                previous=held)
                except FileNotFoundError:
                    pass
                continue
            with os.fdopen(fd, "w") as fh:
                fh.write(body)
            return True
        return False

    def release(self, key: str) -> None:
        try:
            self._lock_path(key).unlink()
        except FileNotFoundError:
            pass

    def in_flight(self, key: str) -> bool:
        return self._lock_path(key).exists()

    def wait_for(self, key: str, timeout_s, poll_s, max_age_s):
        """Wait for another process's fetch. Returns ("answer", rec) | ("released", None) | ("timeout", None)."""
        t_end = time.monotonic() + float(timeout_s)
        while True:
            rec = self.lookup(key, max_age_s)
            if rec is not None:
                return "answer", rec
            if not self.in_flight(key):
                rec = self.lookup(key, max_age_s)
                return ("answer", rec) if rec else ("released", None)
            if time.monotonic() >= t_end:
                return "timeout", None
            time.sleep(float(poll_s))


# ---------- promotion: round store -> Claude Code reference folder (fetched facts only) ----------
def is_fetched_fact(rec: dict) -> tuple[bool, str]:
    """(ok, why). Only an answered info_answer fetched by Tavily or Claude Code, with sources, is a fact."""
    if rec.get("kind") != "info_answer":
        return False, f"kind {rec.get('kind')!r} is not info_answer"
    bad = [k for k in rec if str(k).lower() in DECISION_FIELDS]
    if bad:
        return False, f"decision-type field(s) {bad}"
    if rec.get("status") != "answered":
        return False, f"status {rec.get('status')!r} is not answered"
    if rec.get("answered_by") not in FACT_SOURCES:
        return False, f"answered_by {rec.get('answered_by')!r} is not a fetch"
    if not rec.get("cites"):
        return False, "no sources"
    if rec.get("used_reference"):
        return False, "drawn from the reference folder already"
    return True, ""


def promote_facts(store_dir, reference_dir, records=None) -> dict:
    """Append fetched-fact records from a round store to <reference_dir>/facts.jsonl (append-only, dedup by id).

    st = Store(store_dir)
    recs = st.records() if records is None else records
    ref = Path(reference_dir)
    ref.mkdir(parents=True, exist_ok=True)
    out = ref / REFERENCE_FILE
    have = set()
    if out.is_file():
        have = {json.loads(x).get("id") for x in out.read_text().splitlines() if x.strip()}
    copied, refused = [], []
    keep = ("id", "ts", "store_key", "question", "scope", "answer", "cites", "answered_by", "run_id")
    with _locked(ref / ".facts.lock"):
        with open(out, "a") as fh:
            for r in recs:
                ok, why = is_fetched_fact(r)
                if not ok:
                    refused.append({"id": r.get("id"), "kind": r.get("kind"), "why": why})
                    continue
                if r.get("id") in have:
                    continue
                fh.write(json.dumps({k: r.get(k) for k in keep}, sort_keys=True) + "\n")
                have.add(r.get("id"))
                copied.append(r.get("id"))
    return {"copied": copied, "refused": refused}


# ---------- decisions cache: seal at close ----------
def sealed_path(round_dir, run_id: str) -> Path:
    if not run_id or not re.fullmatch(r"[A-Za-z0-9_.-]+", str(run_id)):
        raise ValueError(f"bad run_id for sealing: {run_id!r}")
    return Path(round_dir) / ARCHIVE_DIR / f"decisions_cache_sealed_{run_id}.jsonl"


def seal_decisions_cache(round_dir, run_id: str) -> Path | None:
    """MOVE <round-dir>/decisions_cache.jsonl to archive/decisions_cache_sealed_<run_id>.jsonl (read-only).
    Nothing is deleted. Refuses (FileExistsError) to overwrite an existing sealed file. No cache -> None."""
    src = Path(round_dir) / DECISIONS_CACHE
    dst = sealed_path(round_dir, run_id)
    if not src.exists():
        return None
    if dst.exists():
        raise FileExistsError(f"{dst} already exists; refusing to overwrite a sealed decisions cache")
    dst.parent.mkdir(parents=True, exist_ok=True)
    with _locked(Path(round_dir) / ".decisions.lock"):
        if dst.exists():
            raise FileExistsError(f"{dst} already exists; refusing to overwrite a sealed decisions cache")
        os.rename(src, dst)
    os.chmod(dst, 0o444)
    return dst

#!/usr/bin/env python3
"""Review ledger core (issue #7): schema validation, sanitising, dedup hashing, parsers, append-only storage.

Stdlib only. Used by scripts/ledger.py (CLI), scripts/ledger_score.py (#8) and scripts/ledger_costs.py (#9).
Record format: ledger/schema/finding.v1.schema.json. Config: harness/ledger.json.

Storage decision: the ledger lives on main (ledger/findings.jsonl), not a data branch. Reasons are in ledger/README.md:
pushes made with the workflow GITHUB_TOKEN do not trigger other workflows (so no CI or paid-audit churn), the scorer,
cost rollup, tests and Pages read the same tree as the code, and there is no second branch to protect or keep in sync.
Append-only is enforced in code (append_records + verify_append_only) and checked again in CI before every push.
"""
from __future__ import annotations

import datetime as _dt
import hashlib
import json
import os
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
CONFIG_PATH = ROOT / "harness" / "ledger.json"
SCHEMA_PATH = ROOT / "ledger" / "schema" / "finding.v1.schema.json"
SCHEMA_TAG = "ssm-ledger/v1.1"   # v1.1 adds receipt/class kinds + review_class; v1 lines stay valid
SCHEMA_TAG_V12 = "ssm-ledger/v1.2"  # v1.2 adds statuses deferred + superseded (status records only)
REVIEW_CLASSES = ("code-review", "spec-review", "legacy")
STATUSES = ("open", "accepted", "rejected", "fixed", "deferred", "superseded")
DECIDED_SCORED = ("accepted", "fixed", "rejected")   # count toward acceptance rate
PARKED = ("deferred", "superseded")                  # decided, not open, not scored, never mirrored
REVIEWERS = {"claude": "Claude", "grok": "Grok", "kimi": "Kimi", "deepseek": "DeepSeek"}


def load_config(path: Path | None = None) -> dict:
    return json.loads((path or CONFIG_PATH).read_text(encoding="utf-8"))


def now_utc() -> str:
    return _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


# ------------------------------------------------------------------ sanitising
_SECRET_PATTERNS = [
    r"sk-ant-[A-Za-z0-9_\-]{8,}", r"sk-(?:proj-|sp-)?[A-Za-z0-9_\-]{16,}", r"xai-[A-Za-z0-9_\-]{16,}",
    r"tvly-[A-Za-z0-9_\-]{6,}", r"gh[pousr]_[A-Za-z0-9]{20,}", r"github_pat_[A-Za-z0-9_]{20,}",
    r"AKIA[0-9A-Z]{16}", r"(?i)bearer\s+[A-Za-z0-9._\-]{12,}", r"-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----",
    r"(?i)(api[_-]?key|token|secret|password)\s*[=:]\s*['\"]?[A-Za-z0-9._\-]{12,}",
]


def trigger_patterns(cfg: dict) -> list[re.Pattern]:
    """Live trigger patterns rebuilt from config parts (slash commands, at-mentions, bracket tags)."""
    s = cfg["sanitise"]
    slash = "|".join(re.escape(w) for w in s["slash_commands"])
    tags = "|".join(re.escape(w) for w in s["bracket_tags"])
    return [re.compile("/" + "(" + slash + r")\b", re.I),
            re.compile(r"\[\s*(" + tags + r")(\s*\d+)?\s*\]", re.I),
            re.compile(r"@([A-Za-z0-9][A-Za-z0-9_\-]*)")]


def contains_trigger(text: str, cfg: dict) -> bool:
    return any(p.search(text or "") for p in trigger_patterns(cfg))


def injection_flags(text: str, cfg: dict) -> list[str]:
    t = (text or "").lower()
    return sorted({p for p in cfg["sanitise"]["injection_phrases"] if re.search(p, t)})


def sanitise(text, cfg: dict, limit: int | None = None) -> str:
    """Make reviewer text safe to store and to post: no secrets, no live triggers or mentions, no HTML/markdown
    tricks, bounded length. Reviewer text is data, never instructions."""
    t = "" if text is None else str(text)
    for pat in _SECRET_PATTERNS:
        t = re.sub(pat, "[redacted]", t)
    t = re.sub(r"<!--[\s\S]*?-->", "", t)                    # hidden HTML comments
    t = re.sub(r"<[^>\n]{1,200}>", "", t)                      # HTML tags
    t = re.sub(r"!\[([^\]]*)\]\([^)]*\)", r"(image: \1)", t)   # images (tracking pixels)
    t = re.sub(r"\[([^\]]+)\]\((https?://[^)\s]+)\)", r"\1 <\2>", t)  # make link targets visible
    t = t.replace("```", "'''")
    slash_p, tag_p, at_p = trigger_patterns(cfg)
    t = slash_p.sub(lambda m: m.group(1), t)                   # drop the slash: command name stays readable
    t = tag_p.sub(lambda m: "(" + m.group(1) + (m.group(2) or "") + ")", t)
    t = at_p.sub(lambda m: m.group(1), t)                      # drop the at-sign: no mentions, no bot wake-ups
    t = re.sub(r"[\u200b-\u200f\u202a-\u202e\u2066-\u2069]", "", t)  # zero-width / bidi controls
    t = re.sub(r"[ \t]+", " ", t).strip()
    lim = limit or int(cfg["sanitise"]["max_text_chars"])
    return t if len(t) <= lim else t[: lim - 1] + "…"


# ------------------------------------------------------------------ hashing / records
def _norm(s) -> str:
    return re.sub(r"\s+", " ", str(s or "")).strip().lower()


def dedup_hash(*parts) -> str:
    return hashlib.sha256("\x1f".join(_norm(p) for p in parts).encode()).hexdigest()


def normalise_severity(sev, cfg: dict) -> str:
    s = _norm(sev)
    s = cfg["severity_aliases"].get(s, s)
    return s if s in cfg["severity_order"] else "note"


def severity_rank(sev: str, cfg: dict) -> int:
    return cfg["severity_order"].index(normalise_severity(sev, cfg))


def make_finding(cfg, *, reviewer, model, severity, domain, file, claim, note, source, verdict=None, event_utc=None,
                 salt: str = "") -> dict:
    raw = f"{claim}\n{note}"
    claim_s, note_s = sanitise(claim, cfg, 600), sanitise(note, cfg)
    h = dedup_hash("finding", reviewer, domain, file, claim_s, salt)  # salt: planted runs stay distinct per run
    return {"schema": SCHEMA_TAG, "kind": "finding", "id": h[:16], "hash": h, "recorded_utc": now_utc(),
            "event_utc": event_utc, "source": source, "reviewer": reviewer, "model": model,
            "severity": normalise_severity(severity, cfg), "domain": sanitise(domain or "general", cfg, 60),
            "file": sanitise(file or "", cfg, 200), "claim": claim_s, "note": note_s,
            "review_verdict": verdict, "injection_flags": injection_flags(raw, cfg), "status": "open"}


def price_for(cfg, model: str | None):
    pr = cfg["prices_usd_per_mtok"]
    if not model:
        return None
    return next((v for k, v in sorted(pr.items(), key=lambda kv: -len(kv[0])) if not k.startswith("_") and model.startswith(k)), None)


def deepseek_offpeak(when_iso: str | None) -> bool:
    if not when_iso:
        return False
    t = _dt.datetime.fromisoformat(when_iso.replace("Z", "+00:00")).astimezone(_dt.timezone.utc)
    return not (t.weekday() < 5 and (1 <= t.hour < 4 or 6 <= t.hour < 10))


def compute_cost(cfg, model, tokens: dict, when_iso=None):
    p = price_for(cfg, model)
    if p is None:
        return None, f"unknown: no price on file for {model}"
    cached, cw = tokens.get("cached") or 0, tokens.get("cache_write") or 0
    miss = max((tokens.get("input") or 0) - cached - cw, 0)
    c = (miss * p["in"] + cached * p["cached"] + cw * p.get("cache_write", p["in"]) + (tokens.get("output") or 0) * p["out"]) / 1e6
    note = "computed from harness/ledger.json prices"
    if "offpeak_factor" in p and deepseek_offpeak(when_iso):
        c *= p["offpeak_factor"]; note += " (off-peak)"
    return round(c, 6), note


def make_cost(cfg, *, reviewer, model, tokens, source, cost_usd=None, cost_basis=None, event_utc=None) -> dict:
    if cost_usd is None:
        cost_usd, cost_basis = compute_cost(cfg, model, tokens, event_utc)
    h = dedup_hash("cost", reviewer, source.get("type"), source.get("ref"), source.get("run_id"), source.get("scope"), model)
    return {"schema": SCHEMA_TAG, "kind": "cost", "id": h[:16], "hash": h, "recorded_utc": now_utc(),
            "event_utc": event_utc, "source": source, "reviewer": reviewer, "model": model,
            "tokens": {k: tokens.get(k) for k in ("input", "cached", "cache_write", "output", "reasoning")},
            "cost_usd": None if cost_usd is None else round(float(cost_usd), 6), "cost_basis": cost_basis or "reported"}


def make_status(finding_id: str, status: str, source: dict, issue_number=None, note: str | None = None) -> dict:
    """Status record. deferred / superseded (v1.2) need a note: the reason or the revisit condition."""
    if status not in STATUSES:
        raise ValueError(f"unknown status {status!r}")
    h = dedup_hash("status", finding_id, status, source.get("ref"))
    rec = {"schema": SCHEMA_TAG_V12 if status in PARKED else SCHEMA_TAG, "kind": "status", "id": h[:16], "hash": h,
           "recorded_utc": now_utc(), "source": source, "finding_id": finding_id, "status": status,
           "issue_number": issue_number}
    if note is not None:
        rec["note"] = note
    elif status in PARKED:
        raise ValueError(f"status {status!r} needs a note (reason / revisit condition)")
    return rec


def make_mirror(finding_id: str, issue_number: int, source: dict) -> dict:
    h = dedup_hash("mirror", finding_id, issue_number)
    return {"schema": SCHEMA_TAG, "kind": "mirror", "id": h[:16], "hash": h, "recorded_utc": now_utc(),
            "source": source, "finding_id": finding_id, "issue_number": int(issue_number)}


